            C++

    using namespace std;

vector<int> etf(int n)
{
    // Computes totient of all numbers from 1 to n
    vector<int> phi(n + 1);
    for (int i = 1; i <= n; i++)
        phi[i] = i;

    // Compute other Phi values
    for (int p = 2; p <= n; p++)
    {
        // If p is prime
        if (phi[p] == p)
        {
            phi[p] = p - 1;
            // Update multiples of p
            for (int i = 2 * p; i <= n; i += p)
            {
                phi[i] = (phi[i] / p) * (p - 1);
            }
        }
    }
    return phi;
}

// Driver code
int main()
{
    int n = 12;
    vector<int> phi = etf(n);

    for (int i = 1; i <= n; i++)
        cout << "Totient of " << i << " is " << phi[i] << endl;

    return 0;
}


