    using namespace std;

int etf(int n)
{
    int res = 1;
    for (int i = 2; i * i <= n; i++)
    {
        int c = 0;
        if (n % i == 0)
        {
            while (n % i == 0)
            {
                c++;
                n /= i;
            }
        }
        if (c > 0)
        {
            int power = (int)pow(i, c - 1);
            int sm = (int)pow(i, c - 1) * (i - 1);
            res *= sm;
        }
    }
    if (n > 1)
    {
        res *= (n - 1);
    }
    return res;
}

